def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (ignore it)
        if '+' in v:
            v = v.split('+')[0]

        # Split into core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_parts = prerelease.split('.')
            prerelease_identifiers = []
            for part in prerelease_parts:
                if part.isdigit():
                    prerelease_identifiers.append((0, int(part)))  # 0 for numeric
                else:
                    prerelease_identifiers.append((1, part))  # 1 for string
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(item):
        v, index = item
        major, minor, patch, prerelease = parse_version(v)

        # For sorting: (major, minor, patch, has_prerelease, prerelease_identifiers)
        # If has_prerelease, it should sort before no prerelease (so False < True)
        if prerelease is None:
            return (major, minor, patch, (1,), index)  # (1,) sorts after (0, ...)
        else:
            return (major, minor, patch, (0,) + tuple(prerelease), index)

    # Add index to preserve order for equal versions
    indexed = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed, key=sort_key)
    return [v for v, _ in sorted_versions]

